/// Apply DWM's real desktop acrylic, with legacy acrylic as a Windows 10 fallback.
/// `suppress_border` is for the creation-time call, before the host is ever
/// shown: DWM composes the default frame ring around the hidden window (the
/// boot ghost), so the border must stay NONE until the first show re-applies
/// real chrome.
fn apply_window_chrome(window: &Window, state: &Arc<Mutex<ShimState>>, suppress_border: bool) -> bool {
    let (dark, glass_native, opaque_panel) = state.lock().map(|s| {
        (
            s.theme == Theme::Dark,
            s.glass_native,
            s.panel_background.is_opaque() || !crate::overlay::platform::transparency_enabled(),
        )
    }).unwrap_or((true, false, false));
    let hwnd = window.hwnd() as HWND;
    let transitions_disabled = 1_i32;
    // Native glass uses the same continuous profile for both HWND regions
    // and CSS. Opaque/acrylic modes use explicit rounded DWM corners so
    // opaque surface clipping matches the visible window silhouette.
    let _ = set_dwm_attribute(hwnd, DWMWA_TRANSITIONS_FORCEDISABLED, &transitions_disabled);
    sync_window_frame_style(window, dark, glass_native, opaque_panel, suppress_border);

    // Keep DWM acrylic for the fallback path. With the native refraction
    // layer active, even reapplying acrylic on a later show paints over the
    // captured image, so keep the main window backdrop disabled.
    // Opaque panels cover the window fully, so the backdrop contributes
    // nothing but square corners poking past the rounded panel — off too.
    let backdrop = if glass_native || opaque_panel {
        DWMSBT_NONE
    } else {
        DWMSBT_TRANSIENTWINDOW
    };
    let native_backdrop = set_dwm_attribute(hwnd, DWMWA_SYSTEMBACKDROP_TYPE, &backdrop);
    // Frame rendering stays on; glass supplies its own region at reveal.
    // BORDER_COLOR above uses DWM's NONE/DEFAULT sentinels, not a tint.
    let available = if opaque_panel {
        // Opaque panels paint solid over an opaque WebView surface
        // (ClearType): no backdrop, and no acrylic fallback — any
        // transparency would void subpixel text.
        false
    } else if native_backdrop {
        true
    } else if glass_native {
        crate::logging::warn(
            "[nex][refract] could not keep the main DWM backdrop disabled on show",
        );
        false
    } else {
        let tint = if dark {
            Some((20, 22, 28, 112))
        } else {
            Some((245, 247, 250, 104))
        };
        window_vibrancy::apply_acrylic(window, tint).is_ok()
    };
    if !available && !opaque_panel {
        crate::logging::info("[nex] native acrylic unavailable; using opaque CSS fallback");
    }
    available
}

fn set_dwm_attribute<T>(hwnd: HWND, attribute: i32, value: &T) -> bool {
    unsafe {
        DwmSetWindowAttribute(
            hwnd,
            attribute as u32,
            value as *const T as *const std::ffi::c_void,
            std::mem::size_of::<T>() as u32,
        ) >= 0
    }
}

/// Reapply the host shape and DWM frame at the point where the window is
/// about to be composed. Region changes send window-position messages, so
/// set the DWM attributes after the region to leave the desired frame state
/// as the final operation before reveal/resize.
fn sync_window_frame(window: &Window, state: &Arc<Mutex<ShimState>>, suppress_border: bool) {
    let (dark, glass_native, opaque_panel) = state
        .lock()
        .map(|s| {
            (
                s.theme == Theme::Dark,
                s.glass_native,
                s.panel_background.is_opaque()
                    || !crate::overlay::platform::transparency_enabled(),
            )
        })
        .unwrap_or((true, false, false));
    sync_window_frame_style(window, dark, glass_native, opaque_panel, suppress_border);
}

fn sync_window_frame_style(
    window: &Window,
    dark: bool,
    glass_native: bool,
    opaque_panel: bool,
    suppress_border: bool,
) {
    let hwnd = window.hwnd() as HWND;
    sync_opaque_window_region(window, opaque_panel);

    let immersive_dark = i32::from(dark);
    let rounded_corners = if glass_native && !opaque_panel {
        windows_sys::Win32::Graphics::Dwm::DWMWCP_DONOTROUND
    } else {
        windows_sys::Win32::Graphics::Dwm::DWMWCP_ROUND
    };
    let _ = set_dwm_attribute(hwnd, DWMWA_USE_IMMERSIVE_DARK_MODE, &immersive_dark);
    let _ = set_dwm_attribute(hwnd, DWMWA_WINDOW_CORNER_PREFERENCE, &rounded_corners);

    // Native glass supplies its own edge. Opaque modes suppress DWM's
    // system frame so it cannot be composited over the solid surface.
    let border_color: u32 = if suppress_border || opaque_panel || (glass_native && !opaque_panel) {
        0xFFFFFFFE
    } else {
        0xFFFFFFFF
    };
    let _ = set_dwm_attribute(
        hwnd,
        windows_sys::Win32::Graphics::Dwm::DWMWA_BORDER_COLOR,
        &border_color,
    );
}

/// Clip the opaque WebView surface to the panel silhouette. Opaque WebView
/// backgrounds are required for ClearType, but otherwise fill the rounded
/// CSS corners with a rectangular black/white surface.
fn sync_opaque_window_region(window: &Window, opaque_panel: bool) {
    use windows_sys::Win32::Foundation::RECT;
    use windows_sys::Win32::Graphics::Gdi::{
        CreateRoundRectRgn, SetWindowRgn,
    };
    use windows_sys::Win32::UI::WindowsAndMessaging::GetWindowRect;

    let hwnd = window.hwnd() as HWND;
    if !opaque_panel {
        unsafe {
            SetWindowRgn(hwnd, std::ptr::null_mut(), 1);
        }
        return;
    }

    let mut window_rect = RECT {
        left: 0,
        top: 0,
        right: 0,
        bottom: 0,
    };
    if unsafe { GetWindowRect(hwnd, &mut window_rect) } == 0 {
        return;
    }
    let scale = window.scale_factor() as f32;
    let radius = (8.0 * scale).round() as i32;
    let width = window_rect.right - window_rect.left;
    let height = window_rect.bottom - window_rect.top;
    if width <= 0 || height <= 0 {
        return;
    }
    unsafe {
        let region = CreateRoundRectRgn(0, 0, width, height, radius * 2, radius * 2);
        if !region.is_null() {
            let _ = SetWindowRgn(hwnd, region, 1);
        }
    }
}

/// Remove the caption frame tao always adds (window_state.rs forces
/// WS_CAPTION on every window). While the host was never shown, DWM still
/// composes that frame even with `DWMWA_BORDER_COLOR=NONE`: first as a
/// rounded ~2px ring, and once the border color is suppressed as a dark
/// 1px top line (`DWMWA_VISIBLE_FRAME_BORDER_THICKNESS=1`). Verified live:
/// stripping the caption bits + WS_POPUP removes both. The overlay is
/// decoration-less and never moves via a caption, so the style is dead
/// weight; the first show re-applies real chrome for the visible panel.
/// (tao re-derives styles on its own state syncs, but the only pre-show
/// sync happens at creation — after that the host goes cloak-on-hide,
/// which DWM does not compose.)
fn strip_caption_frame(hwnd: HWND) {
    use windows_sys::Win32::UI::WindowsAndMessaging::{
        GWL_STYLE, GetWindowLongW, SetWindowPos, SetWindowLongW, SWP_FRAMECHANGED, SWP_NOACTIVATE,
        SWP_NOMOVE, SWP_NOSIZE, SWP_NOZORDER, WS_CAPTION, WS_MAXIMIZEBOX, WS_MINIMIZEBOX,
        WS_POPUP, WS_SYSMENU,
    };
    unsafe {
        let style = GetWindowLongW(hwnd, GWL_STYLE) as u32;
        let stripped = (style & !(WS_CAPTION | WS_SYSMENU | WS_MAXIMIZEBOX | WS_MINIMIZEBOX))
            | WS_POPUP;
        SetWindowLongW(hwnd, GWL_STYLE, stripped as i32);
        let _ = SetWindowPos(
            hwnd,
            std::ptr::null_mut(),
            0,
            0,
            0,
            0,
            SWP_FRAMECHANGED | SWP_NOMOVE | SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE,
        );
    }
}

/// Keep the WebView viewport pinned to the maximum panel size so content
/// beyond the window edge is always rasterized. Window growth then just
/// reveals already-painted pixels — no blank webview frame, no acrylic
/// flash; shrink requires no WebView work at all (the window clips it).
fn keep_webview_viewport_max(webview: &WebView) {
    use wry::dpi::{LogicalPosition, LogicalSize};
    let _ = webview.set_bounds(wry::Rect {
        position: LogicalPosition::new(0.0, 0.0).into(),
        size: LogicalSize::new(WINDOW_WIDTH, MAX_HEIGHT).into(),
    });
}

/// Resize the window and immediately re-assert the oversized WebView
/// viewport (wry snaps it to the window size on WM_SIZE). The spike
/// glass re-aligns to the main window rect (size follows for free).
fn apply_window_height(
    window: &Window,
    webview: Option<&WebView>,
    glass: &mut Option<crate::overlay::refraction::GlassLayer>,
    h: f64,
    state: &Arc<Mutex<ShimState>>,
) {
    window.set_inner_size(LogicalSize::new(WINDOW_WIDTH, h));
    sync_window_frame(window, state, false);
    if let Some(wv) = webview {
        keep_webview_viewport_max(wv);
    }
    if let Some(layer) = glass {
        let scale = window.scale_factor();
        layer.sync_to_main(
            window.hwnd() as isize,
            scale,
            WINDOW_WIDTH,
            h,
            crate::overlay::refraction::physical_px(WINDOW_WIDTH, scale),
            crate::overlay::refraction::physical_px(MAX_HEIGHT, scale),
        );
    }
}

/// Center the window horizontally on the monitor under the cursor and
/// anchor it in the upper third (launcher placement).
fn position_window(window: &Window, _hwnd: HWND) {
    let Some((left, top, right, bottom)) = cursor_monitor_work_area() else {
        return;
    };
    let scale = window.scale_factor();
    let width_phys = (WINDOW_WIDTH * scale) as i32;
    let work_w = right - left;
    let work_h = bottom - top;
    let x = left + (work_w - width_phys) / 2;
    let y = top + (work_h as f32 * 0.25) as i32;
    window.set_outer_position(PhysicalPosition::new(x.max(left), y.max(top)));
}
/// Center a window on the cursor's monitor work area (both axes).
fn position_window_centered(window: &Window) {
    let Some((left, top, right, bottom)) = cursor_monitor_work_area() else {
        return;
    };
    let size = window.inner_size();
    let x = left + (right - left - size.width as i32) / 2;
    let y = top + (bottom - top - size.height as i32) / 2;
    window.set_outer_position(PhysicalPosition::new(x.max(left), y.max(top)));
}

