/* Nex overlay: DWM supplies desktop blur; CSS adds a restrained glass tint. */

@font-face {
  font-family: "InterVariable";
  src: url("data:font/woff2;base64,
... command output truncated for persistence ...
") format("woff2");
  font-weight: 100 900;
  font-style: normal;
}

:root {
  --radius: 8px;
  --row-radius: 8px;
  --pad-x: 16px;
  /* Width of the detail pane; the body divider anchors to it. */
  --font: "InterVariable", "Inter", "Segoe UI", system-ui, -apple-system, sans-serif;

  /* dark palette */
  --bg: #1E1E1E;
  --bg-opaque: #1E1E1E;
  --scrollbar-thumb: rgba(255, 255, 255, 0.28);
  --panel-surface: var(--bg);
  --panel-highlight: rgba(255, 255, 255, 0.12);
  --panel-edge: rgba(255, 255, 255, 0.12);
  --panel-glint: rgba(255, 255, 255, 0.12);
  --panel-sheen: rgba(255, 255, 255, 0.1);
  --panel-reflection: rgba(255, 255, 255, 0.045);
  --panel-bottom-edge: rgba(0, 0, 0, 0.24);
  --border: rgba(255, 255, 255, 0.09);
  --border-strong: rgba(255, 255, 255, 0.14);
  --text: #f4f4f6;
  --text-dim: #c3c9d2;
  --text-faint: #aeb6c2;
  --sel: rgba(255, 255, 255, 0.07);
  --sel-border: rgba(255, 255, 255, 0.08);
  --hover: rgba(255, 255, 255, 0.12);
  --accent: #6ea8fe;
  --divider: rgba(255, 255, 255, 0.06);
  --kbd-bg: rgba(255, 255, 255, 0.08);
  --kbd-pill-bg: transparent;
  --kbd-cap-bg: rgba(255, 255, 255, 0.10);
  --kbd-cap-border: rgba(0, 0, 0, 0.35);
  --icon-bg: rgba(255, 255, 255, 0.06);
  --text-select: rgba(255, 255, 255, 0.28);
  --lock: #6ea8fe;
  --logout: #ffb454;
  --sleep: #b07cff;
  --restart: #4ade80;
  --shutdown: #ff6b6b;
}

html[data-theme="light"] {
  --bg: #ffffff;
  --bg-opaque: #ffffff;
  --scrollbar-thumb: rgba(0, 0, 0, 0.28);
  --panel-highlight: rgba(255, 255, 255, 0.65);
  --panel-edge: rgba(0, 0, 0, 0.10);
  --panel-glint: rgba(255, 255, 255, 0.25);
  --border: rgba(0, 0, 0, 0.1);
  --border-strong: rgba(0, 0, 0, 0.14);
  --text: #16161a;
  --text-dim: #4b515c;
  --text-faint: #68717e;
  --sel: rgba(0, 0, 0, 0.06);
  --sel-border: rgba(0, 0, 0, 0.06);
  --hover: rgba(0, 0, 0, 0.11);
  --accent: #2f6bff;
  --divider: rgba(0, 0, 0, 0.07);
  --kbd-bg: rgba(0, 0, 0, 0.06);
  --kbd-pill-bg: transparent;
  --kbd-cap-bg: #FFFFFF;
  --kbd-cap-border: rgba(0, 0, 0, 0.15);
  --icon-bg: rgba(0, 0, 0, 0.05);
  --text-select: rgba(0, 0, 0, 0.18);
  --lock: #2f6bff;
  --logout: #d97706;
  --sleep: #8b5cf6;
  --restart: #16a34a;
  --shutdown: #dc2626;
}

html[data-native-material="acrylic"] {
  --panel-surface: rgba(17, 20, 27, 0.12);
  --panel-highlight: rgba(255, 255, 255, 0.24);
  --panel-edge: rgba(255, 255, 255, 0.2);
  --panel-glint: rgba(255, 255, 255, 0.12);
  --panel-sheen: rgba(255, 255, 255, 0.075);
  --panel-reflection: rgba(255, 255, 255, 0.035);
  --panel-bottom-edge: rgba(0, 0, 0, 0.3);
}

html[data-theme="light"][data-native-material="acrylic"] {
  --panel-surface: rgba(248, 250, 253, 0.2);
  --panel-highlight: rgba(255, 255, 255, 0.88);
  --panel-edge: rgba(255, 255, 255, 0.72);
  --panel-glint: rgba(255, 255, 255, 0.32);
  --panel-sheen: rgba(255, 255, 255, 0.22);
  --panel-reflection: rgba(255, 255, 255, 0.12);
  --panel-bottom-edge: rgba(55, 72, 101, 0.14);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-user-select: none;
  user-select: none;
}

html,
body {
  width: 100%;
  height: 100%;
  background-color: transparent;
  font-family: var(--font);
  font-weight: 400;
  letter-spacing: 0.2px;
  color: var(--text);
  overflow: hidden;
}

body {
  background: transparent;
}

#panel {
  /* Anchors the glass rim/glint pseudo-elements. The panel fills the
     client area, so absolute children keep their current place. */
  position: relative;
  width: 100%;
  background:
    linear-gradient(136deg, var(--panel-glint) 0%, transparent 28%, transparent 74%, var(--panel-reflection) 100%),
    var(--panel-surface);
  /*border: 1px solid var(--panel-edge);*/
  border-radius: var(--radius);
  box-shadow:
    0 12px 40px rgba(0, 0, 0, 0.36);
  clip-path: inset(-32px round var(--radius));
  /* Contain children (power panel) so their corners round with the
     window and margins don't collapse past the measured height. */
  overflow: hidden;
}
#panel:has(#context-menu:not(.hidden)) {
  overflow: visible;
  clip-path: none;
}

/* ── search row ───────────────────────────────────────────── */
#search-row {
  display: flex;
  align-items: center;
  gap: 12px;
  height: 60px;
  padding: 0 var(--pad-x);
}

#search-icon {
  flex: 0 0 auto;
  fill: none;
  stroke: var(--text-faint);
  stroke-width: 2;
  content: none;
}

@media (prefers-reduced-motion: reduce) {
  html.glass-fading, html.glass-fading * { transition: none !important; }
}

html.glass-native #divider {
  background: color-mix(in srgb, var(--text) 16%, transparent);
}

/* ── opaque panel backgrounds (settings → Background) ────────── */
/* Solid paint for light rooms where glass washes out; glass layer
   stays parked (see glass_active) so this costs no capture. */
html.bg-black #panel {
  background: #000000;
  /* Single hairline only, drawn as an inset ring: outer edges lose
     subpixels asymmetrically (right/bottom) to size rounding, but an
     inset ring always lands fully inside. Region clips outer shadow. */
  border-color: transparent;
  box-shadow: inset 0 0 0 1px var(--panel-edge);
}

html.bg-white #panel {
  background: #ffffff;
  border-color: transparent;
  /* Match black mode's visible hairline: the shared 10% edge var reads
     bare on solid white, so pin a stronger inset ring here only. */
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.16);
}

html.glass-native .row .icon.placeholder {
  background: transparent;
}

